#!/usr/bin/env python3
"""Independent wetting-loop AC analysis; models explicitly illustrative.
Uses native exported component values/pins; never edits schematic or PCB.
"""
from pathlib import Path
import sys,json,subprocess,math,cmath,hashlib,re
from types import SimpleNamespace
ROOT=Path(__file__).resolve().parents[1];W=ROOT/'analysis/source_loop_independent';W.mkdir(exist_ok=True)
# Preserve the native fixture used for this independent pre-correction review.
# It is generated by simulate_a3_inputs.py from the exported native netlist,
# but this script must remain reproducible after the main circuit is corrected.
SNAPSHOT=W/'baseline_native.cir'
if not SNAPSHOT.exists():
 import simulate_a3_inputs as native
 native.deck('independent_baseline_native',mode='contact',emit_only=True)
 SNAPSHOT.write_text((native.WORK/'independent_baseline_native.cir').read_text())
base=SNAPSHOT.read_text().split('.control')[0]
def tokens(ref):return next(l.split() for l in base.splitlines() if l.startswith(ref+' '))
s=SimpleNamespace(E=tokens('R1000')[2],AMP=tokens('R1001')[2],NET=ROOT/'analysis/Universal_Poofer_Control.net')
minus=tokens('R1021')[2]
fixture_sha=next(l.split()[-1] for l in base.splitlines() if l.startswith('* SHA256 '))

def run(name,body,control):
 p=W/(name+'.cir');p.write_text(body+'\n.control\nset wr_vecnames\nset wr_singlescale\n'+control+'\nquit\n.endc\n.end\n')
 r=subprocess.run(['ngspice','-b',str(p)],cwd=W,text=True,capture_output=True,timeout=20)
 (W/(name+'.log')).write_text(r.stdout+r.stderr)
 if r.returncode or 'Error:' in r.stderr: raise RuntimeError(name+':'+r.stderr[-2000:])
 return [list(map(float,l.split())) for l in (W/(name+'.dat')).read_text().splitlines()[1:]]

def deck(bf=100,nf=150,rdrive=2200,tf=30e-9):
 lines=[]
 for l in base.splitlines():
  if l.startswith('R1001 '):l=' '.join(l.split()[:-1])+f' {rdrive}'
  if l.startswith('.model MJD350APPROX'):l=f'.model MJD350APPROX PNP(Is=1e-14 Bf={bf} Br=2 Vaf=150 Ikf=.5 Cje=60p Cjc=20p Tf={tf} Tr=1u)'
  if l.startswith('.model NPNDRIVER'):l=f'.model NPNDRIVER NPN(Is=1e-14 Bf={nf} Br=3 Vaf=100 Cje=8p Cjc=4p Tf=.5n Tr=200n)'
  lines.append(l)
 return '\n'.join(lines)

def metrics(rows,ao=100000,gbw=1200000,extra_pole=None):
 cross=[];previous=None;maxg=0
 for r in rows:
  f=r[0];beta=complex(r[1],r[2]);plant=complex(r[3],r[4]);out=complex(r[5],r[6]);A=ao/(1+1j*f/(gbw/ao))
  if extra_pole:A/=1+1j*f/extra_pole
  loop=A*beta;mag=abs(loop);phase=math.degrees(cmath.phase(loop));pm=(180+phase)%360
  if pm>180:pm-=360
  if previous and (previous[1]-1)*(mag-1)<=0:
   cross.append({'frequency_hz':f,'phase_margin_deg':pm,'direction':'falling' if mag<previous[1] else 'rising'})
  if f<=2: maxg=max(maxg,abs(plant))
  previous=(f,mag)
 return {'plant_dc_gain_abs':maxg,'unity_crossings':cross}

# Independently assert every implemented filter against the current native export.
import simulate_a3_inputs as current
native_filter_checks=[]
assert len(current.COMP)==len(json.loads((ROOT/'bom/design-components.json').read_text())), 'Native/metadata component-count mismatch'
for ch in range(1,10):
 rb=1000+30*(ch-1);rr=f'R{rb+24}';cc=f'C{140+ch}'
 amp='U20' if ch<=4 else 'U21' if ch<=8 else 'U22';plus=[3,5,10,12][(ch-1)%4]
 emit=current.pn(f'Q{100+ch}',3);filtered=current.pn(amp,plus)
 assert emit==f'IN{ch}_WET_EMIT'
 assert filtered==f'IN{ch}_EMIT_F'
 assert {current.pn(rr,1),current.pn(rr,2)}=={emit,filtered}
 assert current.value(rr)=='10k'
 assert {current.pn(cc,1),current.pn(cc,2)}=={filtered,'GND'}
 assert current.value(cc).startswith('100nF')
 assert 'R_0805' in current.child(current.COMP[rr],'footprint')[1]
 assert 'C_0805' in current.child(current.COMP[cc],'footprint')[1]
 native_filter_checks.append({'channel':ch,'resistor':rr,'resistance_ohm':10000,'capacitor':cc,'capacitance_f':100e-9,'emitter_net':emit,'filtered_net':filtered,'amplifier':amp,'noninverting_pin':plus,'return_net':'GND','passive_package':'0805','status':'pass'})
current.deck('independent_final_native',mode='contact',emit_only=True)
FINAL_SNAPSHOT=W/'final_native.cir'
FINAL_SNAPSHOT.write_text((current.WORK/'independent_final_native.cir').read_text())
final_base=FINAL_SNAPSHOT.read_text().split('.control')[0]
final_results=[]
for bf,nf,tf in [(30,100,30e-9),(100,150,30e-9),(240,300,30e-9),(240,300,100e-9)]:
 name=f'final_b{bf}_n{nf}_tf{tf:g}'.replace('.','p').replace('-','m')
 body=final_base
 body=re.sub(r'^\.model MJD350APPROX.*$',f'.model MJD350APPROX PNP(Is=1e-14 Bf={bf} Br=2 Vaf=150 Ikf=.5 Cje=60p Cjc=20p Tf={tf} Tr=1u)',body,flags=re.M)
 body=re.sub(r'^\.model NPNDRIVER.*$',f'.model NPNDRIVER NPN(Is=1e-14 Bf={nf} Br=3 Vaf=100 Cje=8p Cjc=4p Tf=.5n Tr=200n)',body,flags=re.M)
 e=current.node('Q101',3);amp=current.node('U20',1);mi=current.node('U20',2);pl=current.node('U20',3)
 biasrows=run(name+'_op',body,f'op\nwrdata {name}_op.dat v(AMPSOURCE) v({amp}) v({e}) v(wet_i)')
 body='\n'.join(l for l in body.splitlines() if not l.startswith(('BAMP ','BAMPSTAGE ')))
 body+=f'\nVTEST AMPSOURCE 0 DC {biasrows[-1][1]} AC 1\nRAMP AMPSOURCE {amp} 50\nBBETA BETA 0 V={{V({mi})-V({pl})}}'
 rows=run(name+'_ac',body,f'ac dec 100 .1 100Meg\nwrdata {name}_ac.dat real(v(BETA)) imag(v(BETA)) real(v({e})) imag(v({e})) real(v({amp})) imag(v({amp}))')
 final_results.append({'pnp_bf':bf,'npn_bf':nf,'pnp_tf_seconds':tf,'drive_resistance_ohm':2200,'emitter_filter':[10000,100e-9],'native_filter_resistor':'R1024','native_filter_capacitor':'C141','native_plus_net':current.pn('U20',3),'dc_wetting_ma':1000*biasrows[-1][4],'fixture':str(W/(name+'_ac.cir')),'single_pole_1p2MHz':metrics(rows),'two_pole_second_at_3MHz':metrics(rows,extra_pole=3e6)})

results=[]
for bf,nf,tf in [(30,100,30e-9),(100,150,30e-9),(240,300,30e-9),(240,300,100e-9)]:
 for rdrive,filter_rc in [(2200,None),(10000,None),(47000,None),(100000,None),(2200,(10000,100e-9)),(10000,(10000,100e-9))]:
  tag=f'b{bf}_n{nf}_tf{tf:g}_r{rdrive}_f{bool(filter_rc)}'.replace('.','p').replace('-','m')
  body=deck(bf,nf,rdrive,tf)
  biasrows=run(tag+'_op',body,f'op\nwrdata {tag}_op.dat v(AMPSOURCE) v({s.AMP}) v({s.E}) v(wet_i)')
  bias=biasrows[-1][1]
  body='\n'.join(l for l in body.splitlines() if not l.startswith(('BAMP ','BAMPSTAGE ')))
  body+=f'\nVTEST AMPSOURCE 0 DC {bias} AC 1\nRAMP AMPSOURCE {s.AMP} 50'
  sensed=s.E
  if filter_rc:
   sensed='FILTERED_EMITTER';body+=f'\nRFILTER {s.E} {sensed} {filter_rc[0]}\nCFILTER {sensed} 0 {filter_rc[1]}'
  body+=f'\nBBETA BETA 0 V={{V({minus})-V({sensed})}}'
  rows=run(tag+'_ac',body,f'ac dec 100 .1 100Meg\nwrdata {tag}_ac.dat real(v(BETA)) imag(v(BETA)) real(v({s.E})) imag(v({s.E})) real(v({s.AMP})) imag(v({s.AMP}))')
  item={'pnp_bf':bf,'npn_bf':nf,'pnp_tf_seconds':tf,'drive_resistance_ohm':rdrive,'emitter_filter':filter_rc,'dc_wetting_ma':1000*biasrows[-1][4], 'fixture':str(W/(tag+'_ac.cir')),'single_pole_1p2MHz':metrics(rows),'two_pole_second_at_3MHz':metrics(rows,extra_pole=3e6)}
  results.append(item)
  print(json.dumps({k:v for k,v in item.items() if k not in ['fixture','two_pole_second_at_3MHz']}))
transients=[]
for bf,nf in [(100,150),(240,300)]:
 for filtered in [False,True]:
  name=f'small_step_b{bf}_n{nf}_filter{filtered}'
  fixture=W/f'b{bf}_n{nf}_tf3em08_r2200_f{filtered}_ac.cir'
  body=fixture.read_text().split('.control')[0]
  body='\n'.join(l for l in body.splitlines() if not l.startswith(('VTEST ','BBETA ')))
  sensed='FILTERED_EMITTER' if filtered else s.E
  body+=f'\nGAMP 0 AMPSTATE {sensed} {minus} 1\nRAMPSTATE AMPSTATE 0 100k\nCAMPSTATE AMPSTATE 0 {1/(2*math.pi*1.2e6)}\nBOUT AMPSOURCE 0 V={{max(.02,min(10.5,V(AMPSTATE)))}}\nISTEP {s.E} 0 PULSE(0 1u 1m 1n 1n 1m 10m)\n.nodeset V(AMPSTATE)=.675'
  rows=run(name,body,f'tran 50n 4m 0 50n\nwrdata {name}.dat v({s.E}) v({minus}) v({s.AMP}) v(wet_i)')
  late=[z[4]*1000 for z in rows if z[0]>.003]
  transients.append({'pnp_bf':bf,'npn_bf':nf,'emitter_filter':filtered,'late_min_ma':min(late),'late_max_ma':max(late),'peak_ma':max(z[4]*1000 for z in rows),'min_ma':min(z[4]*1000 for z in rows),'fixture':str(W/(name+'.cir'))})
comparisons=[]
for f in final_results:
 c=next(x for x in results if x['pnp_bf']==f['pnp_bf'] and x['npn_bf']==f['npn_bf'] and x['pnp_tf_seconds']==f['pnp_tf_seconds'] and x['drive_resistance_ohm']==2200 and x['emitter_filter'] and x['emitter_filter'][0]==10000 and math.isclose(x['emitter_filter'][1],1e-7))
 delta=abs(c['single_pole_1p2MHz']['unity_crossings'][0]['phase_margin_deg']-f['single_pole_1p2MHz']['unity_crossings'][0]['phase_margin_deg'])
 margins=[c['phase_margin_deg'] for c in f['two_pole_second_at_3MHz']['unity_crossings']]
 assert margins and min(margins)>45, 'Corrected native loop lost illustrative phase margin'
 comparisons.append({'pnp_bf':f['pnp_bf'],'npn_bf':f['npn_bf'],'pnp_tf_seconds':f['pnp_tf_seconds'],'candidate_to_actual_phase_delta_deg':delta,'implemented_min_two_pole_margin_deg':min(margins),'criterion':'Actual corrected illustrative margin >45 degrees; later protection changes need not be numerically identical to the earlier candidate','status':'pass'})
report={'native_netlist_sha256':fixture_sha,'baseline_native_netlist_sha256':fixture_sha,'final_native_netlist_sha256':hashlib.sha256(s.NET.read_bytes()).hexdigest(),'final_native_components':len(current.COMP),'implemented_native_filter_checks':native_filter_checks,'implemented_final_results':final_results,'candidate_to_implemented_comparison':comparisons,'current_native_netlist_sha256':hashlib.sha256(s.NET.read_bytes()).hexdigest(),'method':'Open-loop nonlinear transistor plant biased using native closed DC fixture, AC injected before50R amplifier output model. beta=Vlocalminus−Vfilteredemitter. Returnratio=A*beta; A=100k singlepole GBW1.2MHz; additional3MHz pole illustrative phase sensitivity. Reference buffer AC treated low impedance with native200R/10u; clamp diode and backup limiter retained.','limitations':['Generic BJT transistor models not manufacturer corners. BF variation at20mA illustrative, not guaranteed ranges.','Opamp Aol/phase/output impedance approximated; calculated phase margins are topology evidence, not physical qualification.','No PCB parasitics, temperature corners, output-current limiting or overload recovery in AC. Manufacturer model transient handled separately.'],'results':results,'small_perturbation_transients':transients}
(ROOT/'analysis/source-loop-independent.json').write_text(json.dumps(report,indent=2)+'\n')
